      let currentTurn = 'X';
      let gameActive = true;

      function checkWin(player) {
        const winningCombinations = [
          [0,1,2], [3,4,5], [6,7,8], // rows
          [0,3,6], [1,4,7], [2,5,8], // columns
          [0,4,8], [2,4,6]           // diagonals
        ];
        return winningCombinations.some(combo => 
          combo.every(index => boardState[index] === player)
        );
      }

      function checkDraw() {
        return boardState.every(cell => cell !== null);
      }

      function resetGame() {
        boardState = Array(9).fill(null);
        currentTurn = 'X';
        gameActive = true;
        turnDisplay.textContent = `Turn: ${currentTurn}`;
        announce.textContent = '';
        board.innerHTML = '';
        populateBoard();
      }

      function populateBoard() {
        boardState.forEach((cell, index) => {
          const button = document.createElement('button');
          button.textContent = cell || '';
          button.className = 'cell';
          if (!gameActive) button.disabled = true;
          button.addEventListener('click', () => {
            if (gameActive && !cell) {
              boardState[index] = currentTurn;
              button.textContent = currentTurn;
              if (checkWin(currentTurn)) {
                announce.textContent = `${currentTurn} wins!`;
                gameActive = false;
                turnDisplay.textContent = '';
              } else if (checkDraw()) {
                announce.textContent = 'Draw!';
                gameActive = false;
                turnDisplay.textContent = '';
              } else {
                currentTurn = currentTurn === 'X' ? 'O' : 'X';
                turnDisplay.textContent = `Turn: ${currentTurn}`;
              }
            }
          });
          board.appendChild(button);
        });
      }

      resetGame();

      restart.addEventListener('click', resetGame);
    } catch (error) {
      document.getElementById('error').textContent = error.message;
    }
  </script>
