    </style>
</head>
<body>
    <header>
        <div class="status" id="status">X's turn</div>
    </header>
    <main>
        <div class="board">
            <button id="cell-0" role="button"></button>
            <button id="cell-1" role="button"></button>
            <button id="cell-2" role="button"></button>
            <button id="cell-3" role="button"></button>
            <button id="cell-4" role="button"></button>
            <button id="cell-5" role="button"></button>
            <button id="cell-6" role="button"></button>
            <button id="cell-7" role="button"></button>
            <button id="cell-8" role="button"></button>
        </div>
        <div class="status" id="status"></div>
        <div class="controls">
            <button class="restart" id="restart">Restart</button>
        </div>
    </main>
    <div id="alert" role="alert" aria-live="assertive" style="color:#ff0000"></div>
    <script>
        try {
            let cells = Array.from({length:9}, (_,i) => document.getElementById(`cell-${i}`));
            let currentTurn = 'X';
            cells.forEach(cell => cell.addEventListener('click', handleCellClick));
            document.getElementById('restart').addEventListener('click', restartGame);
        } catch (error) {
            document.getElementById('alert').textContent = error.message;
        }

        function handleCellClick(e) {
            const cell = e.target;
            if (!cell.textContent && !document.getElementById('alert').style.display === 'none') return;
            cell.textContent = currentTurn;
            if (checkWin()) {
                cell.style.backgroundColor = '#4E6E69';
                alertWin(currentTurn);
            } else if (!cells.some(c => !c.textContent)) {
                alertWin('Draw');
            } else {
                currentTurn = currentTurn === 'X' ? 'O' : 'X';
                document.getElementById('status').textContent = `${currentTurn}'s turn`;
            }
        }

        function checkWin() {
            const winningCombos = [
                [0,1,2], [3,4,5], [6,7,8],
                [0,3,6], [1,4,7], [2,5,8],
                [0,4,8], [2,4,6]
            ];
            for (const combo of winningCombos) {
                if (cells[combo[0]].textContent &&
                    cells[combo[0]].textContent === cells[combo[1]].textContent &&
                    cells[combo[1]].textContent === cells[combo[2]].textContent) {
                    return true;
                }
            }
            return false;
        }

        function alertWin(winner) {
            const resultText = winner === 'Draw' ? 'Game drawn!' : `${winner} wins`; 
            document.getElementById('status').textContent = resultText;
            document.getElementById('restart').style.display = 'block';
            cells.forEach(cell => cell.removeEventListener('click', handleCellClick));
        }

        function restartGame() {
            try {
                document.getElementById('status').textContent = 'X\'s turn';
                document.getElementById('restart').style.display = 'none';
                cells.forEach(cell => cell.textContent = '');
                cells.forEach(cell => cell.addEventListener('click', handleCellClick));
                cell.style.backgroundColor = '';
            } catch (e) {
                document.getElementById('alert').textContent += ` Restart error: ${e.message}`;
            }
        }
    </script>
</body>
</html>
